#!/usr/bin/env node
'use strict';

/**
 * Minimal, dependency-free packager for Gemini CLI skills.
 * Validates the skill, then zips it into <skill-name>.skill.
 *
 * Usage:
 *   node package_skill.cjs [skill-folder] [output-dir]
 * Defaults: skill-folder = this script's directory; output-dir = cwd.
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const EXCLUDED = new Set(['package_skill.cjs']);

// ---------- Validation ----------

function validate(folder) {
  const sk = path.join(folder, 'SKILL.md');
  if (!fs.existsSync(sk)) throw new Error('SKILL.md not found');

  const text = fs.readFileSync(sk, 'utf8');
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) throw new Error('SKILL.md is missing YAML frontmatter');
  const fm = m[1];

  const nameMatch = fm.match(/^name:\s*(.+)$/m);
  const descMatch = fm.match(/^description:\s*(.+)$/m);
  if (!nameMatch) throw new Error('frontmatter is missing required field: name');
  if (!descMatch) throw new Error('frontmatter is missing required field: description');

  const name = nameMatch[1].trim();
  const desc = descMatch[1].trim();
  if (!/^[a-z0-9][a-z0-9-]{0,63}$/.test(name)) {
    throw new Error(`invalid skill name "${name}": use lowercase letters, digits, and hyphens (max 64 chars)`);
  }
  if (path.basename(folder) !== name) {
    throw new Error(`folder name "${path.basename(folder)}" does not match skill name "${name}"`);
  }
  if (desc.length < 20) throw new Error('description is too short; describe what the skill does and when to use it');
  if (/TODO/i.test(text)) throw new Error('SKILL.md still contains TODO placeholders');

  // Check that files referenced from SKILL.md (scripts/, references/, assets/) exist.
  const refs = [...text.matchAll(/(?:scripts|references|assets)\/[A-Za-z0-9._-]+/g)].map((x) => x[0]);
  for (const r of refs) {
    if (!fs.existsSync(path.join(folder, r))) {
      throw new Error(`SKILL.md references missing file: ${r}`);
    }
  }
  return name;
}

// ---------- Minimal ZIP writer (stored entries, UTF-8 names) ----------

function crc32(buf) {
  let table = crc32.table;
  if (!table) {
    table = crc32.table = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      table[n] = c;
    }
  }
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = table[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function dosDateTime(d) {
  const time = (d.getHours() << 11) | (d.getMinutes() << 5) | Math.floor(d.getSeconds() / 2);
  const date = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { time, date };
}

function buildZip(files) {
  const chunks = [];
  const central = [];
  let offset = 0;
  const { time, date } = dosDateTime(new Date());

  for (const f of files) {
    const nameBuf = Buffer.from(f.name, 'utf8');
    const crc = crc32(f.data);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4);         // version needed
    local.writeUInt16LE(0x0800, 6);     // flags: UTF-8 names
    local.writeUInt16LE(0, 8);          // method: stored
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(f.data.length, 18);
    local.writeUInt32LE(f.data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);         // extra field length
    chunks.push(local, nameBuf, f.data);

    const cen = Buffer.alloc(46);
    cen.writeUInt32LE(0x02014b50, 0);   // central directory signature
    cen.writeUInt16LE(20, 4);           // version made by
    cen.writeUInt16LE(20, 6);           // version needed
    cen.writeUInt16LE(0x0800, 8);       // flags: UTF-8 names
    cen.writeUInt16LE(0, 10);           // method: stored
    cen.writeUInt16LE(time, 12);
    cen.writeUInt16LE(date, 14);
    cen.writeUInt32LE(crc, 16);
    cen.writeUInt32LE(f.data.length, 20);
    cen.writeUInt32LE(f.data.length, 24);
    cen.writeUInt16LE(nameBuf.length, 28);
    cen.writeUInt16LE(0, 30);           // extra field length
    cen.writeUInt16LE(0, 32);           // comment length
    cen.writeUInt16LE(0, 34);           // disk number start
    cen.writeUInt16LE(0, 36);           // internal attrs
    cen.writeUInt32LE(0, 38);           // external attrs
    cen.writeUInt32LE(offset, 42);      // local header offset
    central.push(cen, nameBuf);

    offset += local.length + nameBuf.length + f.data.length;
  }

  const centralSize = central.reduce((a, b) => a + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);    // end of central directory signature
  eocd.writeUInt16LE(0, 4);             // disk number
  eocd.writeUInt16LE(0, 6);             // disk with central dir
  eocd.writeUInt16LE(files.length, 8);  // entries on this disk
  eocd.writeUInt16LE(files.length, 10); // total entries
  eocd.writeUInt32LE(centralSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);            // comment length

  return Buffer.concat([...chunks, ...central, eocd]);
}

// ---------- Collect files ----------

function collect(dir, prefix, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (EXCLUDED.has(entry.name)) continue;
    if (entry.name.endsWith('.skill')) continue;
    const full = path.join(dir, entry.name);
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) collect(full, rel, out);
    else if (entry.isFile()) out.push({ name: rel, data: fs.readFileSync(full) });
  }
}

// ---------- Main ----------

function main() {
  const folder = path.resolve(process.argv[2] || __dirname);
  const outDir = path.resolve(process.argv[3] || process.cwd());
  const name = validate(folder);
  const files = [];
  collect(folder, '', files);
  const zip = buildZip(files);
  const outFile = path.join(outDir, `${name}.skill`);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(outFile, zip);
  console.log(`Success: packaged ${files.length} file(s) into ${outFile} (${zip.length} bytes).`);
}

try {
  main();
} catch (err) {
  console.error(`Packaging failed: ${err.message}`);
  process.exit(1);
}

