    cen.writeUInt32LE(0x02014b50, 0);   // central directory signature
    cen.writeUInt16LE(20, 4);           // version made by
    cen.writeUInt16LE(20, 6);           // version needed
    cen.writeUInt16LE(0x0800, 8);       // flags: UTF-8 names
    cen.writeUInt16LE(0, 10);           // method: stored
    cen.writeUInt16LE(time, 12);
    cen.writeUInt16LE(date, 14);
    cen.writeUInt32LE(crc, 16);
    cen.writeUInt32LE(f.data.length, 20);
    cen.writeUInt32LE(f.data.length, 24);
    cen.writeUInt16LE(nameBuf.length, 28);
    cen.writeUInt16LE(0, 30);           // extra field length
    cen.writeUInt16LE(0, 32);           // comment length
    cen.writeUInt16LE(0, 34);           // disk number start
    cen.writeUInt16LE(0, 36);           // internal attrs
    cen.writeUInt32LE(0, 38);           // external attrs
    cen.writeUInt32LE(offset, 42);      // local header offset
    central.push(cen, nameBuf);

    offset += local.length + nameBuf.length + f.data.length;
  }

  const centralSize = central.reduce((a, b) => a + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);    // end of central directory signature
  eocd.writeUInt16LE(0, 4);             // disk number
  eocd.writeUInt16LE(0, 6);             // disk with central dir
  eocd.writeUInt16LE(files.length, 8);  // entries on this disk
  eocd.writeUInt16LE(files.length, 10); // total entries
  eocd.writeUInt32LE(centralSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);            // comment length

  return Buffer.concat([...chunks, ...central, eocd]);
}

// ---------- Collect files ----------

function collect(dir, prefix, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (EXCLUDED.has(entry.name)) continue;
    if (entry.name.endsWith('.skill')) continue;
    const full = path.join(dir, entry.name);
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) collect(full, rel, out);
    else if (entry.isFile()) out.push({ name: rel, data: fs.readFileSync(full) });
  }
}

// ---------- Main ----------

function main() {
  const folder = path.resolve(process.argv[2] || __dirname);
  const outDir = path.resolve(process.argv[3] || process.cwd());
  const name = validate(folder);
  const files = [];
  collect(folder, '', files);
  const zip = buildZip(files);
  const outFile = path.join(outDir, `${name}.skill`);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(outFile, zip);
  console.log(`Success: packaged ${files.length} file(s) into ${outFile} (${zip.length} bytes).`);
}

try {
  main();
} catch (err) {
  console.error(`Packaging failed: ${err.message}`);
  process.exit(1);
}

