#!/usr/bin/env node
'use strict';

/**
 * Slack Web API client for Gemini CLI.
 * Sends one request to https://slack.com/api/<endpoint> and prints an
 * LLM-friendly result. No third-party dependencies (Node 18+ global fetch).
 *
 * Usage:
 *   node slack_api.cjs --endpoint chat.postMessage --data '{"channel":"C123","text":"hi"}'
 *   node slack_api.cjs --endpoint conversations.list --query '{"types":"public_channel","limit":100}'
 *   node slack_api.cjs --endpoint users.info --query '{"user":"U123"}'
 *
 * Options:
 *   --endpoint <name>   Slack API method (required)
 *   --data <json>       JSON body for POST requests
 *   --query <json>      JSON object merged into the query string
 *   --method <GET|POST> Override HTTP method (default: POST if --data given, else GET)
 *   --token <token>     Override token (default: $SLACK_BOT_TOKEN || $SLACK_TOKEN)
 *   --no-truncate       Print the full response instead of truncating
 *   -h, --help          Show this help
 *
 * Environment:
 *   SLACK_BOT_TOKEN  Bot token (xoxb-...) — preferred
 *   SLACK_TOKEN      User token (xoxp-...)
 *
 * Exit codes: 0 success, 1 Slack API or usage error, 2 network error.
 */

const BASE_URL = 'https://slack.com/api';
const TIMEOUT_MS = 15000;
const MAX_OUTPUT_CHARS = 12000;

function usage() {
  console.log(`Slack Web API client

Usage:
  node slack_api.cjs --endpoint <method> [options]

Options:
  --endpoint <name>   Slack API method (e.g. chat.postMessage)
  --data <json>       JSON body for POST requests
  --query <json>      JSON object merged into the query string
  --method <GET|POST> Override HTTP method (default: POST if --data given, else GET)
  --token <token>     Override token (default: \$SLACK_BOT_TOKEN || \$SLACK_TOKEN)
  --no-truncate       Print the full response instead of truncating
  -h, --help          Show this help

Examples:
  node slack_api.cjs --endpoint chat.postMessage --data '{"channel":"C123","text":"hi"}'
  node slack_api.cjs --endpoint conversations.list --query '{"types":"public_channel","limit":100}'
  node slack_api.cjs --endpoint users.info --query '{"user":"U123"}'

Environment:
  SLACK_BOT_TOKEN  Bot token (xoxb-...) — preferred
  SLACK_TOKEN      User token (xoxp-...)`);
}

function parseArgs(argv) {
  const opts = { help: false, endpoint: null, data: null, query: null, method: null, token: null, truncate: true };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const next = () => {
      const v = argv[++i];
      if (v === undefined) {
        console.error(`Error: ${arg} requires a value`);
        opts.help = true;
      }
      return v;
    };
    switch (arg) {
      case '-h':
      case '--help':
        opts.help = true;
        break;
      case '--endpoint':
        opts.endpoint = next();
        break;
      case '--data':
        opts.data = next();
        break;
      case '--query':
        opts.query = next();
        break;
      case '--method':
        opts.method = next() ? next().toUpperCase() : null;
        break;
      case '--token':
        opts.token = next();
        break;
      case '--no-truncate':
        opts.truncate = false;
        break;
      default:
        if (arg.startsWith('-')) {
          console.error(`Unknown option: ${arg}`);
          opts.help = true;
        } else if (!opts.endpoint) {
          opts.endpoint = arg;
        } else {
          console.error(`Unexpected argument: ${arg}`);
          opts.help = true;
        }
    }
  }
  return opts;
}

function parseJson(raw, label) {
  try {
    return JSON.parse(raw);
  } catch {
    console.error(`Error: --${label} is not valid JSON`);
    process.exit(1);
  }
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (opts.help) {
    usage();
    process.exit(0);
  }
  if (!opts.endpoint) {
    console.error('Error: --endpoint is required');
    usage();
    process.exit(1);
  }

  const token = opts.token || process.env.SLACK_BOT_TOKEN || process.env.SLACK_TOKEN;
  if (!token) {
    console.error('Error: no Slack token. Set SLACK_BOT_TOKEN (bot) or SLACK_TOKEN (user), or pass --token.');
    process.exit(1);
  }

  const body = opts.data ? parseJson(opts.data, 'data') : null;
  const query = opts.query ? parseJson(opts.query, 'query') : {};
  if (typeof query !== 'object' || query === null || Array.isArray(query)) {
    console.error('Error: --query must be a JSON object');
    process.exit(1);
  }

  const method = opts.method || (body ? 'POST' : 'GET');
  const url = new URL(`${BASE_URL}/${opts.endpoint}`);
  for (const [key, value] of Object.entries(query)) {
    url.searchParams.set(key, String(value));
  }

  const headers = { Authorization: `Bearer ${token}` };
  if (method === 'POST' && body) headers['Content-Type'] = 'application/json';

  let res;
  try {
    res = await fetch(url, {
      method,
      headers,
      body: method === 'POST' && body ? JSON.stringify(body) : undefined,
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
  } catch (err) {
    console.error(`Error: network request failed: ${err.message}`);
    process.exit(2);
  }

  const text = await res.text();
  let json = null;
  try {
    json = JSON.parse(text);
  } catch {
    // non-JSON body; printed raw below
  }

  if (json !== null && json.ok === false) {
    const detail = json.detail ? ` — ${json.detail}` : '';
    console.error(`Slack API error (HTTP ${res.status}): ${json.error}${detail}`);
    process.exit(1);
  }

  const output = json !== null ? JSON.stringify(json) : text;
  const header = `Slack API response (${method} ${opts.endpoint}, HTTP ${res.status}):`;
  if (opts.truncate && output.length > MAX_OUTPUT_CHARS) {
    console.log(`${header} truncated:`);
    console.log(output.slice(0, MAX_OUTPUT_CHARS));
    console.log(`...[truncated ${output.length - MAX_OUTPUT_CHARS} chars; re-run with --no-truncate for full output]`);
  } else {
    console.log(header);
    console.log(output);
  }

  const nextCursor = json && json.response_metadata && json.response_metadata.next_cursor;
  if (nextCursor) {
    console.log(`Pagination: pass --query '{"cursor":"${nextCursor}"}' (plus original params) to fetch the next page.`);
  }
  process.exit(0);
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(2);
});

#!/usr/bin/env node
'use strict';

/**
 * Task-local skill packager: validates a skill folder (frontmatter, naming,
 * referenced resources) and packages it as a distributable .skill zip
 * (stored, uncompressed entries — valid per the ZIP spec). No dependencies.
 *
 * Usage:
 *   node package_skill.cjs <skill-folder> [output-dir]
 */

const fs = require('fs');
const path = require('path');

// --- CRC32 ---
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function dosDateTime(d) {
  const time = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
  const date = (((d.getFullYear() - 1980) & 0x7f) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { time, date };
}

function listFiles(dir, prefix = '') {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) out.push(...listFiles(path.join(dir, entry.name), rel));
    else out.push({ abs: path.join(dir, entry.name), rel });
  }
  return out;
}

// --- Validation ---
function validate(skillDir) {
  const errors = [];
  const name = path.basename(skillDir);
  if (!/^[a-z0-9-]{1,64}$/.test(name)) {
    errors.push(`invalid skill name "${name}" (use lowercase letters, digits, hyphens; <= 64 chars)`);
  }
  const skPath = path.join(skillDir, 'SKILL.md');
  if (!fs.existsSync(skPath)) {
    errors.push('SKILL.md is missing');
    return errors;
  }
  const content = fs.readFileSync(skPath, 'utf8');
  const fm = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!fm) {
    errors.push('SKILL.md has no YAML frontmatter');
  } else {
    if (!/^name:\s*\S+/m.test(fm[1])) errors.push('frontmatter is missing "name"');
    if (!/^description:\s*\S+/m.test(fm[1])) errors.push('frontmatter is missing "description"');
    if (/TODO/i.test(content)) errors.push('SKILL.md still contains TODO placeholders');
  }
  // Check referenced bundled resources exist.
  for (const ref of content.matchAll(/(?:references|scripts|assets)\/[A-Za-z0-9._-]+/g)) {
    if (!fs.existsSync(path.join(skillDir, ref[0]))) {
      errors.push(`SKILL.md references missing resource: ${ref[0]}`);
    }
  }
  return errors;
}

// --- ZIP writer (store method) ---
function buildZip(files) {
  const chunks = [];
  const central = [];
  let offset = 0;
  for (const f of files) {
    const data = fs.readFileSync(f.abs);
    const nameBuf = Buffer.from(f.rel, 'utf8');
    const crc = crc32(data);
    const { time, date } = dosDateTime(fs.statSync(f.abs).mtime);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4);         // version needed
    local.writeUInt16LE(0x0800, 6);     // UTF-8 filename flag
    local.writeUInt16LE(0, 8);          // method: store
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);         // extra length
    chunks.push(local, nameBuf, data);

    const cen = Buffer.alloc(46);
    cen.writeUInt32LE(0x02014b50, 0);   // central directory signature
    cen.writeUInt16LE(20, 4);           // version made by
    cen.writeUInt16LE(20, 6);           // version needed
    cen.writeUInt16LE(0x0800, 8);       // UTF-8 flag
    cen.writeUInt16LE(0, 10);           // method: store
    cen.writeUInt16LE(time, 12);
    cen.writeUInt16LE(date, 14);
    cen.writeUInt32LE(crc, 16);
    cen.writeUInt32LE(data.length, 20);
    cen.writeUInt32LE(data.length, 24);
    cen.writeUInt16LE(nameBuf.length, 28);
    cen.writeUInt16LE(0, 30);           // extra length
    cen.writeUInt16LE(0, 32);           // comment length
    cen.writeUInt16LE(0, 34);           // disk number start
    cen.writeUInt16LE(0, 36);           // internal attrs
    cen.writeUInt32LE(0, 38);           // external attrs
    cen.writeUInt32LE(offset, 42);      // local header offset
    central.push(cen, nameBuf);

    offset += local.length + nameBuf.length + data.length;
  }

  const centralStart = offset;
  const centralBuf = Buffer.concat(central);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);    // EOCD signature
  eocd.writeUInt16LE(0, 4);             // disk number
  eocd.writeUInt16LE(0, 6);             // disk with central dir
  eocd.writeUInt16LE(files.length, 8);  // entries on this disk
  eocd.writeUInt16LE(files.length, 10); // total entries
  eocd.writeUInt32LE(centralBuf.length, 12);
  eocd.writeUInt32LE(centralStart, 16);
  eocd.writeUInt16LE(0, 20);            // comment length
  return Buffer.concat([...chunks, centralBuf, eocd]);
}

function main() {
  const args = process.argv.slice(2);
  const skillDir = path.resolve(args[0] || '.');
  const outDir = path.resolve(args[1] || '.');
  if (!fs.existsSync(skillDir)) {
    console.error(`Skill folder not found: ${skillDir}`);
    process.exit(1);
  }

  const errors = validate(skillDir);
  if (errors.length) {
    console.error('Skill validation failed:');
    for (const e of errors) console.error(`  - ${e}`);
    process.exit(1);
  }

  const files = listFiles(skillDir).sort((a, b) => a.rel.localeCompare(b.rel));
  if (!files.length) {
    console.error('Skill folder is empty');
    process.exit(1);
  }

  const zip = buildZip(files);
  const name = path.basename(skillDir);
  const outFile = path.join(outDir, `${name}.skill`);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(outFile, zip);

  // Self-verify: EOCD signature at end, entry count, central directory signature.
  const check = fs.readFileSync(outFile);
  const eocd = check.length - 22;
  if (check.readUInt32LE(eocd) !== 0x06054b50) {
    console.error('Self-verify failed: missing EOCD record');
    process.exit(1);
  }
  const entries = check.readUInt16LE(eocd + 10);
  if (entries !== files.length) {
    console.error(`Self-verify failed: expected ${files.length} entries, found ${entries}`);
    process.exit(1);
  }
  if (check.readUInt32LE(check.readUInt32LE(eocd + 16)) !== 0x02014b50) {
    console.error('Self-verify failed: bad central directory');
    process.exit(1);
  }

  console.log(`Validation passed. Packaged ${files.length} file(s) into ${outFile}`);
  console.log('Contents:');
  for (const f of files) {
    console.log(`  ${f.rel} (${fs.statSync(f.abs).size} bytes)`);
  }
}

main();

#!/usr/bin/env node
'use strict';

/**
 * Minimal, dependency-free packager for Gemini CLI skills.
 * Validates the skill, then zips it into <skill-name>.skill.
 *
 * Usage:
 *   node package_skill.cjs [skill-folder] [output-dir]
 * Defaults: skill-folder = this script's directory; output-dir = cwd.
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const EXCLUDED = new Set(['package_skill.cjs']);

// ---------- Validation ----------

function validate(folder) {
  const sk = path.join(folder, 'SKILL.md');
  if (!fs.existsSync(sk)) throw new Error('SKILL.md not found');

  const text = fs.readFileSync(sk, 'utf8');
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) throw new Error('SKILL.md is missing YAML frontmatter');
  const fm = m[1];

  const nameMatch = fm.match(/^name:\s*(.+)$/m);
  const descMatch = fm.match(/^description:\s*(.+)$/m);
  if (!nameMatch) throw new Error('frontmatter is missing required field: name');
  if (!descMatch) throw new Error('frontmatter is missing required field: description');

  const name = nameMatch[1].trim();
  const desc = descMatch[1].trim();
  if (!/^[a-z0-9][a-z0-9-]{0,63}$/.test(name)) {
    throw new Error(`invalid skill name "${name}": use lowercase letters, digits, and hyphens (max 64 chars)`);
  }
  if (path.basename(folder) !== name) {
    throw new Error(`folder name "${path.basename(folder)}" does not match skill name "${name}"`);
  }
  if (desc.length < 20) throw new Error('description is too short; describe what the skill does and when to use it');
  if (/TODO/i.test(text)) throw new Error('SKILL.md still contains TODO placeholders');

  // Check that files referenced from SKILL.md (scripts/, references/, assets/) exist.
  const refs = [...text.matchAll(/(?:scripts|references|assets)\/[A-Za-z0-9._-]+/g)].map((x) => x[0]);
  for (const r of refs) {
    if (!fs.existsSync(path.join(folder, r))) {
      throw new Error(`SKILL.md references missing file: ${r}`);
    }
  }
  return name;
}

// ---------- Minimal ZIP writer (stored entries, UTF-8 names) ----------

function crc32(buf) {
  let table = crc32.table;
  if (!table) {
    table = crc32.table = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      table[n] = c;
    }
  }
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = table[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function dosDateTime(d) {
  const time = (d.getHours() << 11) | (d.getMinutes() << 5) | Math.floor(d.getSeconds() / 2);
  const date = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { time, date };
}

function buildZip(files) {
  const chunks = [];
  const central = [];
  let offset = 0;
  const { time, date } = dosDateTime(new Date());

  for (const f of files) {
    const nameBuf = Buffer.from(f.name, 'utf8');
    const crc = crc32(f.data);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4);         // version needed
    local.writeUInt16LE(0x0800, 6);     // flags: UTF-8 names
    local.writeUInt16LE(0, 8);          // method: stored
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(f.data.length, 18);
    local.writeUInt32LE(f.data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);         // extra field length
    chunks.push(local, nameBuf, f.data);

    const cen = Buffer.alloc(46);
    cen.writeUInt32LE(0x02014b50, 0);   // central directory signature
    cen.writeUInt16LE(20, 4);           // version made by
    cen.writeUInt16LE(20, 6);           // version needed
    cen.writeUInt16LE(0x0800, 8);       // flags: UTF-8 names
    cen.writeUInt16LE(0, 10);           // method: stored
    cen.writeUInt16LE(time, 12);
    cen.writeUInt16LE(date, 14);
    cen.writeUInt32LE(crc, 16);
    cen.writeUInt32LE(f.data.length, 20);
    cen.writeUInt32LE(f.data.length, 24);
    cen.writeUInt16LE(nameBuf.length, 28);
    cen.writeUInt16LE(0, 30);           // extra field length
    cen.writeUInt16LE(0, 32);           // comment length
    cen.writeUInt16LE(0, 34);           // disk number start
    cen.writeUInt16LE(0, 36);           // internal attrs
    cen.writeUInt32LE(0, 38);           // external attrs
    cen.writeUInt32LE(offset, 42);      // local header offset
    central.push(cen, nameBuf);

    offset += local.length + nameBuf.length + f.data.length;
  }

  const centralSize = central.reduce((a, b) => a + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);    // end of central directory signature
  eocd.writeUInt16LE(0, 4);             // disk number
  eocd.writeUInt16LE(0, 6);             // disk with central dir
  eocd.writeUInt16LE(files.length, 8);  // entries on this disk
  eocd.writeUInt16LE(files.length, 10); // total entries
  eocd.writeUInt32LE(centralSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);            // comment length

  return Buffer.concat([...chunks, ...central, eocd]);
}

// ---------- Collect files ----------

function collect(dir, prefix, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (EXCLUDED.has(entry.name)) continue;
    if (entry.name.endsWith('.skill')) continue;
    const full = path.join(dir, entry.name);
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) collect(full, rel, out);
    else if (entry.isFile()) out.push({ name: rel, data: fs.readFileSync(full) });
  }
}

// ---------- Main ----------

function main() {
  const folder = path.resolve(process.argv[2] || __dirname);
  const outDir = path.resolve(process.argv[3] || process.cwd());
  const name = validate(folder);
  const files = [];
  collect(folder, '', files);
  const zip = buildZip(files);
  const outFile = path.join(outDir, `${name}.skill`);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(outFile, zip);
  console.log(`Success: packaged ${files.length} file(s) into ${outFile} (${zip.length} bytes).`);
}

try {
  main();
} catch (err) {
  console.error(`Packaging failed: ${err.message}`);
  process.exit(1);
}

#!/usr/bin/env node
'use strict';

/**
 * Task-local packager for the slack-api skill.
 * Validates the skill folder, then zips it into <skill-name>.skill
 * (a standard ZIP archive with a .skill extension, stored entries,
 * UTF-8 names — compatible with `unzip` and `gemini skills install`).
 *
 * Usage:
 *   node build_skill.cjs <skill-folder> [output-dir]
 */

const fs = require('fs');
const path = require('path');

// ---------- ZIP primitives ----------

function crc32(buf) {
  if (!crc32.table) {
    crc32.table = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crc32.table[n] = c;
    }
  }
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = crc32.table[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function buildZip(files) {
  const chunks = [];
  const central = [];
  let offset = 0;
  const now = new Date();
  const time = (now.getHours() << 11) | (now.getMinutes() << 5) | Math.floor(now.getSeconds() / 2);
  const date = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();

  for (const f of files) {
    const nameBuf = Buffer.from(f.name, 'utf8');
    const crc = crc32(f.data);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4);         // version needed
    local.writeUInt16LE(0x0800, 6);     // UTF-8 name flag
    local.writeUInt16LE(0, 8);          // method: stored
    local.writeUInt16LE(time, 10);
    local.writeUInt16LE(date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(f.data.length, 18); // compressed size
    local.writeUInt32LE(f.data.length, 22); // uncompressed size
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);         // extra field length
    chunks.push(local, nameBuf, f.data);

    const cen = Buffer.alloc(46);
    cen.writeUInt32LE(0x02014b50, 0);   // central directory signature
    cen.writeUInt16LE(20, 4);           // version made by
    cen.writeUInt16LE(20, 6);           // version needed
    cen.writeUInt16LE(0x0800, 8);       // UTF-8 name flag
    cen.writeUInt16LE(0, 10);           // method: stored
    cen.writeUInt16LE(time, 12);
    cen.writeUInt16LE(date, 14);
    cen.writeUInt32LE(crc, 16);
    cen.writeUInt32LE(f.data.length, 20);
    cen.writeUInt32LE(f.data.length, 24);
    cen.writeUInt16LE(nameBuf.length, 28);
    cen.writeUInt16LE(0, 30);           // extra field length
    cen.writeUInt16LE(0, 32);           // comment length
    cen.writeUInt16LE(0, 34);           // disk number start
    cen.writeUInt16LE(0, 36);           // internal attributes
    cen.writeUInt32LE(0, 38);           // external attributes
    cen.writeUInt32LE(offset, 42);      // local header offset
    central.push(cen, nameBuf);

    offset += local.length + nameBuf.length + f.data.length;
  }

  const centralSize = central.reduce((a, b) => a + b.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);    // end of central directory signature
  eocd.writeUInt16LE(0, 4);             // disk number
  eocd.writeUInt16LE(0, 6);             // disk with central directory
  eocd.writeUInt16LE(files.length, 8);  // entries on this disk
  eocd.writeUInt16LE(files.length, 10); // total entries
  eocd.writeUInt32LE(centralSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);            // comment length

  return Buffer.concat([...chunks, ...central, eocd]);
}

// ---------- Validation ----------

function validate(folder) {
  const sk = path.join(folder, 'SKILL.md');
  if (!fs.existsSync(sk)) throw new Error('SKILL.md not found');

  const text = fs.readFileSync(sk, 'utf8');
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) throw new Error('SKILL.md is missing YAML frontmatter');
  const fm = m[1];

  const nameMatch = fm.match(/^name:\s*(.+)$/m);
  const descMatch = fm.match(/^description:\s*(.+)$/m);
  if (!nameMatch) throw new Error('frontmatter is missing required field: name');
  if (!descMatch) throw new Error('frontmatter is missing required field: description');

  const name = nameMatch[1].trim();
  const desc = descMatch[1].trim();
  if (!/^[a-z0-9][a-z0-9-]{0,63}$/.test(name)) {
    throw new Error(`invalid skill name "${name}": use lowercase letters, digits, and hyphens (max 64 chars)`);
  }
  if (path.basename(folder) !== name) {
    throw new Error(`folder name "${path.basename(folder)}" does not match skill name "${name}"`);
  }
  if (desc.length < 20) throw new Error('description is too short; describe what the skill does and when to use it');
  if (/TODO/i.test(text)) throw new Error('SKILL.md still contains TODO placeholders');

  const refs = [...text.matchAll(/(?:scripts|references|assets)\/[A-Za-z0-9._-]+/g)].map((x) => x[0]);
  for (const r of refs) {
    if (!fs.existsSync(path.join(folder, r))) throw new Error(`SKILL.md references missing file: ${r}`);
  }
  return name;
}

// ---------- Collect files ----------

function collect(dir, prefix, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.endsWith('.skill')) continue;
    const full = path.join(dir, entry.name);
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) collect(full, rel, out);
    else if (entry.isFile()) out.push({ name: rel, data: fs.readFileSync(full) });
  }
}

// ---------- Main ----------

function main() {
  const folder = path.resolve(process.argv[2] || 'slack-api');
  const outDir = path.resolve(process.argv[3] || '.');
  const name = validate(folder);
  const files = [];
  collect(folder, '', files);
  const zip = buildZip(files);
  const outFile = path.join(outDir, `${name}.skill`);
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(outFile, zip);
  console.log(`Success: packaged ${files.length} file(s) into ${outFile} (${zip.length} bytes).`);
  console.log('Entries: ' + files.map((f) => f.name).join(', '));
}

try {
  main();
} catch (err) {
  console.error(`Packaging failed: ${err.message}`);
  process.exit(1);
}

